script:
var VECompendiaKnowledgeSync = Class.create();
VECompendiaKnowledgeSync.prototype = {
  initialize: function () {
    this.source = 'Compendia';
    this.base = 'https://api.compendia.no';
    this.contentBase = gs.getProperty('varenergi.compendia.content_base_url', 'https://cp.compendia.no');
    this.customer = gs.getProperty('varenergi.compendia.customer_slug', 'varenergi');
    this.handbook = gs.getProperty('varenergi.compendia.handbook_slug', 'personal');
    this.handbooks = this.parseHandbooks(gs.getProperty('varenergi.compendia.handbooks', 'employee,leadership-portal,personal,personal-offshore'));
    this.kb = gs.getProperty('varenergi.compendia.kb');
    this.author = gs.getProperty('varenergi.compendia.author_user');
    this.token = '';
    this.fileCache = {};
    this.requestDelayMs = parseInt(gs.getProperty('varenergi.compendia.request_delay_ms', '500'), 10);
    this.maxRetries = parseInt(gs.getProperty('varenergi.compendia.max_retries', '3'), 10);
  },

  syncAll: function (limit, dryRun) {
    var max = parseInt(limit || gs.getProperty('varenergi.compendia.sync.max_per_run', '50'), 10);
    var out = {ok: true, dry_run: dryRun === true, handbooks: this.handbooks.length, total: 0, scanned: 0, processed: 0, skipped: 0, failed: 0, errors: [], results: []};
    for (var h = 0; h < this.handbooks.length; h++) {
      var handbook = this.handbooks[h];
      var pages = this.getPages(handbook.slug);
      out.total += pages.length;
      for (var i = 0; i < pages.length; i++) {
        out.scanned++;
        if (out.processed >= max) break;
        var page = pages[i];
        page._handbook_slug = handbook.slug;
        page._handbook_name = handbook.name;
        try {
          var existing = this.getExistingByExternalKey(handbook.slug, page.id);
          if (!this.needsSync(page, existing)) {
            out.skipped++;
            continue;
          }
          var result = this.syncPage(handbook, page.id, dryRun === true);
          out.results.push(result);
          if (result.ok) out.processed++;
          else { out.failed++; out.errors.push(result); }
        } catch (ex) {
          var failed = this.errorResult('syncAll', page, ex);
          out.failed++;
          out.errors.push(failed);
          gs.error('Compendia sync page failed: ' + JSON.stringify(failed));
        }
      }
    }
    out.ok = out.failed === 0;
    return out;
  },

  syncPage: function (handbook, id, dryRun) {
    try {
      var page = this.getPage(handbook.slug, id);
      page._handbook_slug = handbook.slug;
      page._handbook_name = handbook.name;
      var externalKey = this.externalKey(handbook.slug, page.id);
      var existing = this.getExistingByExternalKey(handbook.slug, page.id);
      var action = existing ? 'updated' : 'inserted';
      var category = this.getHandbookCategory(handbook);
      if (dryRun === true) return {ok: true, dry_run: true, action: action, external_key: externalKey, page_id: String(page.id), handbook: handbook.slug, title: page.title, target_state: this.targetWorkflowState(), category: category ? String(category.getUniqueValue()) : ''};
      if (!existing) { existing = new GlideRecord('kb_knowledge'); existing.initialize(); }
      this.upsertStage(page, handbook, 'loaded', action, '', null);
      this.mapPageToArticle(page, handbook, category, existing);
      var sysId = action == 'inserted' ? existing.insert() : existing.update();
      if (!sysId) throw 'kb_knowledge ' + action + ' returned no sys_id';

      // Attachment handling happens after the article exists because ServiceNow
      // stores files against the target record's sys_id.
      var article = new GlideRecord('kb_knowledge');
      if (!article.get(String(sysId))) throw 'kb_knowledge ' + action + ' could not be reloaded for attachments sys_id=' + sysId;
      var attachmentResult = this.syncArticleAttachments(article, page, handbook);
      if (!attachmentResult.ok) {
        var attachmentError = 'Attachment sync failed for ' + externalKey + ': ' + attachmentResult.errors.join(' | ');
        this.upsertStage(page, handbook, 'error', action, attachmentError, String(sysId));
        return {ok: false, stage: 'attachments', action: action, sys_id: String(sysId), external_key: externalKey, page_id: String(page.id), handbook: handbook.slug, title: page.title, target_state: this.targetWorkflowState(), attachments: attachmentResult, error: attachmentError};
      }

      this.upsertStage(page, handbook, 'processed', action, '', String(sysId));
      return {ok: true, action: action, sys_id: String(sysId), external_key: externalKey, page_id: String(page.id), handbook: handbook.slug, title: page.title, target_state: this.targetWorkflowState(), attachments: attachmentResult};
    } catch (ex) {
      var failed = this.errorResult('syncPage', {id: id, _handbook_slug: handbook.slug}, ex);
      try { this.upsertStage({_handbook_slug: handbook.slug, id: id, title: ''}, handbook, 'error', 'failed', failed.error, null); } catch (stageEx) {}
      gs.error('Compendia syncPage failed: ' + JSON.stringify(failed));
      return failed;
    }
  },

  getExistingByExternalKey: function (handbookSlug, id) {
    var key = this.externalKey(handbookSlug, id);
    var gr = new GlideRecord('kb_knowledge');
    var qc = gr.addQuery('u_compendia_page_id', key);
    qc.addOrCondition('u_compendia_page_id', String(id));
    gr.addQuery('u_compendia_url', 'CONTAINS', '/' + handbookSlug + '/');
    gr.setLimit(1);
    gr.query();
    return gr.next() ? gr : null;
  },

  needsSync: function (page, existing) {
    if (!existing) return true;
    if (String(existing.getValue('kb_knowledge_base')) != String(this.kb)) return true;
    if (String(existing.getValue('workflow_state')) != this.targetWorkflowState()) return true;
    if (this.hasRelativeContentUrl(existing.getValue('text'))) return true;
    if (String(existing.getValue('u_compendia_page_id')) != this.externalKey(page._handbook_slug, page.id)) return true;
    if (!page.modified) return true;
    return String(existing.getValue('u_compendia_modified')) != this.toGlideDateTime(page.modified);
  },

  mapPageToArticle: function (page, handbook, category, gr) {
    gr.setValue('kb_knowledge_base', this.kb);
    if (category) gr.setValue('kb_category', category.getUniqueValue());
    if (this.author) gr.setValue('author', this.author);
    gr.setValue('short_description', String(page.title || '').substring(0, 100));
    gr.setValue('text', this.normalizeContent(page.content || ''));
    gr.setValue('article_type', 'text');
    gr.setValue('workflow_state', this.targetWorkflowState());
    if (this.targetWorkflowState() == 'published') gr.setValue('published', new GlideDate().getValue());
    else gr.setValue('published', '');
    gr.setValue('active', true);
    gr.setValue('valid_to', '2100-01-01');
    gr.setValue('u_compendia_page_id', this.externalKey(handbook.slug, page.id));
    gr.setValue('u_compendia_url', page.url || this.contentBase + '/' + this.customer + '/' + handbook.slug + '/' + page.id);
    if (page.modified) gr.setValue('u_compendia_modified', this.toGlideDateTime(page.modified));
    gr.setValue('meta', this.buildMeta(page, handbook));
    gr.setValue('meta_description', 'Synced from Compendia ' + handbook.name + '. Tags: ' + this.tagNames(page));
  },

  upsertStage: function (page, handbook, state, action, error, targetSysId) {
    var key = this.externalKey(handbook.slug, page.id);
    var gr = new GlideRecord('u_compendia_import_staging');
    gr.addQuery('u_external_key', key);
    gr.setLimit(1);
    gr.query();
    if (!gr.next()) gr.initialize();
    gr.setValue('u_source', this.source);
    gr.setValue('u_customer_slug', this.customer);
    gr.setValue('u_handbook_slug', handbook.slug);
    gr.setValue('u_handbook_name', handbook.name);
    gr.setValue('u_external_id', String(page.id || ''));
    gr.setValue('u_external_key', key);
    gr.setValue('u_external_url', page.url || this.contentBase + '/' + this.customer + '/' + handbook.slug + '/' + page.id);
    if (page.modified) gr.setValue('u_external_modified', this.toGlideDateTime(page.modified));
    gr.setValue('u_title', String(page.title || '').substring(0, 300));
    gr.setValue('u_language', this.languageForHandbook(handbook.slug));
    gr.setValue('u_tags', this.tagNames(page));
    gr.setValue('u_category_path', handbook.name);
    gr.setValue('u_content', this.normalizeContent(page.content || ''));
    gr.setValue('u_payload', JSON.stringify(page).substring(0, 8000));
    gr.setValue('u_sync_state', state);
    gr.setValue('u_action', action || '');
    gr.setValue('u_error_message', String(error || '').substring(0, 4000));
    gr.setValue('u_processed_on', new GlideDateTime());
    if (targetSysId) gr.setValue('u_target_article', targetSysId);
    return gr.isNewRecord() ? gr.insert() : gr.update();
  },

  getHandbookCategory: function (handbook) {
    var gr = new GlideRecord('kb_category');
    gr.addQuery('parent_id', this.kb);
    gr.addQuery('value', handbook.slug);
    gr.setLimit(1);
    gr.query();
    if (gr.next()) {
      // parent_id is a document ID; parent_table is required for portal breadcrumb resolution.
      if (gr.getValue('parent_table') != 'kb_knowledge_base') {
        gr.setValue('parent_table', 'kb_knowledge_base');
        gr.update();
      }
      return gr;
    }
    gr.initialize();
    gr.setValue('parent_table', 'kb_knowledge_base');
    gr.setValue('parent_id', this.kb);
    gr.setValue('label', handbook.name);
    gr.setValue('value', handbook.slug);
    gr.setValue('active', true);
    var id = gr.insert();
    return id ? gr : null;
  },

  normalizeContent: function (html) {
    var out = String(html || '').replace(/(src|href)=(['"])\/(?!\/)/gi, '$1=$2' + this.contentBase + '/');
    return this.formatCollapsibles(out);
  },

  removeDuplicateCollapseMarkers: function (html) {
    // Compendia can emit adjacent empty editor markers for the same section.
    // Remove only those duplicates; intervening content starts a new section.
    var source = String(html || '');
    var previousEnd = -1;
    var previousTitle = null;
    var marker = /<div\b([^>]*)>\s*<\/div>/gi;
    return source.replace(marker, function (whole, attrs, offset) {
      var classes = /\bclass\s*=\s*(["'])(.*?)\1/i.exec(attrs);
      var title = /\bdata-collapse-title\s*=\s*(["'])(.*?)\1/i.exec(attrs);
      if (!classes || !/(^|\s)collapsable(\s|$)/.test(classes[2]) || !title) return whole;
      var duplicate = previousTitle === title[2] && previousEnd >= 0 &&
        /^\s*$/.test(source.substring(previousEnd, offset));
      previousTitle = title[2];
      previousEnd = offset + whole.length;
      return duplicate ? '' : whole;
    });
  },


  formatCollapsibles: function (html) {
    var out = this.removeDuplicateCollapseMarkers(html);
    out = out.replace(/<div([^>]*class=['"][^'"]*collapsed-closed-title[^'"]*['"][^>]*)>([\s\S]*?)<\/div>\s*<div([^>]*class=['"][^'"]*collapsed-closed-content[^'"]*['"][^>]*)>([\s\S]*?)<\/div>/gi,
      '<details class="ve-compendia-accordion" style="margin:16px 0;"><summary style="display:block;background:#e5e7e7;padding:10px 44px 10px 12px;font-weight:700;cursor:pointer;position:relative;">$2<span style="float:right;font-size:20px;line-height:16px;">&#8964;</span></summary><div style="border:1px solid #e5e7e7;border-top:0;padding:12px;">$4</div></details>');
    out = out.replace(/<div([^>]*class=['"][^'"]*collapsed-closed-title[^'"]*['"][^>]*)>([\s\S]*?)<\/div>/gi,
      '<details class="ve-compendia-accordion" style="margin:16px 0;"><summary style="display:block;background:#e5e7e7;padding:10px 44px 10px 12px;font-weight:700;cursor:pointer;position:relative;">$2<span style="float:right;font-size:20px;line-height:16px;">&#8964;</span></summary><div style="padding:12px 0 0 0;"></div></details>');
    out = out.replace(/<div([^>]*class=['"][^'"]*collapsable[^'"]*['"][^>]*data-collapse-title=['"]([^'"]+)['"][^>]*)>[\s\S]*?<\/div>/gi,
      '<details class="ve-compendia-accordion" style="margin:16px 0;"><summary style="display:block;background:#e5e7e7;padding:10px 44px 10px 12px;font-weight:700;cursor:pointer;position:relative;">$2<span style="float:right;font-size:20px;line-height:16px;">&#8964;</span></summary><div style="padding:12px 0 0 0;"></div></details>');
    out = out.replace(/<div([^>]*data-collapse-title=['"]([^'"]+)['"][^>]*class=['"][^'"]*collapsable[^'"]*['"][^>]*)>[\s\S]*?<\/div>/gi,
      '<details class="ve-compendia-accordion" style="margin:16px 0;"><summary style="display:block;background:#e5e7e7;padding:10px 44px 10px 12px;font-weight:700;cursor:pointer;position:relative;">$2<span style="float:right;font-size:20px;line-height:16px;">&#8964;</span></summary><div style="padding:12px 0 0 0;"></div></details>');
    out = this.groupCollapsableMarkers(out);
    return out;
  },

  groupCollapsableMarkers: function (html) {
    var marker = /<details class="ve-compendia-accordion"[\s\S]*?<\/details>/ig;
    var matches = [];
    var m;
    while ((m = marker.exec(html)) !== null) matches.push({start: m.index, end: marker.lastIndex, tag: m[0]});
    if (matches.length < 1) return html;
    var out = html.substring(0, matches[0].start);
    for (var i = 0; i < matches.length; i++) {
      var contentStart = matches[i].end;
      var contentEnd = i + 1 < matches.length ? matches[i + 1].start : html.length;
      var content = html.substring(contentStart, contentEnd);
      out += matches[i].tag.replace('<div style="padding:12px 0 0 0;"></div></details>', '<div style="padding:12px 0 0 0;">' + content + '</div></details>');
    }
    return out;
  },

  hasPlainAttachmentList: function (html) {
    var text = String(html || '');
    return /blocks-link-template/i.test(text) && /<li\b[^>]*>(?!\s*<a\b)[\s\S]{3,300}?<\/li>/i.test(text);
  },

  syncArticleAttachments: function (article, page, handbook) {
    var result = {ok: true, matched: 0, attached: 0, reused: 0, linked: 0, errors: []};
    article.setValue('display_attachments', true);

    var matches = this.getAttachmentMatches(page, handbook);
    result.matched = matches.length;
    if (!matches.length) {
      article.update();
      return result;
    }

    var body = String(article.getValue('text') || '');
    for (var i = 0; i < matches.length; i++) {
      try {
        var attachment = this.ensureFileAttachment(article, matches[i].file._handbook_slug || handbook.slug, matches[i].file);
        if (attachment.reused) result.reused++;
        else result.attached++;
        var replaced = this.linkAttachmentTitle(body, matches[i].title, attachment.sys_id);
        body = replaced.html;
        if (replaced.linked) result.linked++;
      } catch (ex) {
        result.ok = false;
        result.errors.push('file_id=' + matches[i].file.id + ' title=' + matches[i].title + ' error=' + String(ex));
      }
    }

    if (body != String(article.getValue('text') || '')) article.setValue('text', body);
    article.update();
    return result;
  },

  getAttachmentMatches: function (page, handbook) {
    var titles = this.extractAttachmentTitles(page.content || '');
    if (!titles.length) return [];

    var files = this.getCandidateFiles(handbook.slug);
    var matches = [];
    var usedFiles = {};
    for (var i = 0; i < titles.length; i++) {
      var file = this.matchFileByTitle(titles[i], files);
      if (!file || usedFiles[String(file.id)]) continue;
      usedFiles[String(file.id)] = true;
      matches.push({title: titles[i], file: file});
    }
    return matches;
  },

  extractAttachmentTitles: function (html) {
    var source = String(html || '');
    var templateLists = [];
    var listMatch;
    var listRegex = /<ul\b[^>]*class=['"][^'"]*blocks-link-template-items[^'"]*['"][^>]*>[\s\S]*?<\/ul>/ig;
    while ((listMatch = listRegex.exec(source)) !== null) templateLists.push(listMatch[0]);
    if (templateLists.length) source = templateLists.join(' ');

    var out = [];
    var seen = {};
    var li = /<li\b[^>]*>([\s\S]*?)<\/li>/ig;
    var match;
    while ((match = li.exec(source)) !== null) {
      if (/<a\b/i.test(match[1])) continue;
      var title = this.stripHtml(match[1]).replace(/^\s+|\s+$/g, '');
      if (title.length < 5 || title.length > 250) continue;
      var key = this.normalizeAttachmentTitle(title);
      if (!key || seen[key]) continue;
      seen[key] = true;
      out.push(title);
    }
    return out;
  },

  getFiles: function (handbookSlug) {
    if (this.fileCache[handbookSlug]) return this.fileCache[handbookSlug];
    var data = this.getJson('/' + this.customer + '/' + handbookSlug + '/api/v1/files');
    this.fileCache[handbookSlug] = data.files || [];
    return this.fileCache[handbookSlug];
  },

  getCandidateFiles: function (preferredHandbookSlug) {
    var combined = [];
    var seen = {};
    this.addFilesForHandbook(combined, seen, preferredHandbookSlug);
    for (var i = 0; i < this.handbooks.length; i++) {
      if (this.handbooks[i].slug != preferredHandbookSlug) this.addFilesForHandbook(combined, seen, this.handbooks[i].slug);
    }
    return combined;
  },

  addFilesForHandbook: function (combined, seen, handbookSlug) {
    var files = this.getFiles(handbookSlug);
    for (var i = 0; i < files.length; i++) {
      var id = String(files[i].id || '');
      var key = handbookSlug + ':' + id;
      if (!id || seen[key]) continue;
      seen[key] = true;
      var item = {};
      for (var prop in files[i]) item[prop] = files[i][prop];
      item._handbook_slug = handbookSlug;
      combined.push(item);
    }
  },

  matchFileByTitle: function (title, files) {
    var target = this.normalizeAttachmentTitle(title);
    if (!target) return null;

    var best = null;
    var bestScore = 0;
    for (var i = 0; i < files.length; i++) {
      var fileTitle = this.normalizeAttachmentTitle(files[i].title || files[i].name || files[i].file_name || '');
      if (!fileTitle) continue;

      var score = 0;
      if (fileTitle == target) score = 10000;
      else if (fileTitle.indexOf(target) >= 0) score = target.length;
      else if (target.indexOf(fileTitle) >= 0) score = fileTitle.length;
      else if (this.containsWordsInOrder(fileTitle, target)) score = target.length - 1;

      if (score > bestScore) {
        best = files[i];
        bestScore = score;
      }
    }

    return bestScore >= 8 ? best : null;
  },

  containsWordsInOrder: function (container, needle) {
    var words = String(needle || '').split(/\s+/);
    var pos = 0;
    for (var i = 0; i < words.length; i++) {
      if (!words[i]) continue;
      var found = String(container || '').indexOf(words[i], pos);
      if (found < 0) return false;
      pos = found + words[i].length;
    }
    return true;
  },

  ensureFileAttachment: function (article, handbookSlug, file) {
    var fileId = String(file.id || '');
    if (!fileId) throw 'Compendia file has no id';

    var fileName = this.attachmentFileName(file.title || file.name || ('compendia-file-' + fileId), '');
    var existing = this.findExistingAttachment(article.getUniqueValue(), fileName);
    if (existing) return existing;

    for (var attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (attempt > 0 || this.requestDelayMs > 0) gs.sleep(this.requestDelayMs * (attempt + 1));
      var rm = new sn_ws.RESTMessageV2();
      rm.setHttpMethod('get');
      rm.setEndpoint(this.base + '/' + this.customer + '/' + handbookSlug + '/api/v1/files/' + encodeURIComponent(fileId) + '/download');
      rm.setRequestHeader('Authorization', 'Bearer ' + this.getToken());
      rm.setRequestHeader('Accept', '*/*');
      rm.setHttpTimeout(60000);
      rm.saveResponseBodyAsAttachment('kb_knowledge', article.getUniqueValue(), fileName);
      var res = rm.execute();
      var status = res.getStatusCode();
      var attachmentSysId = String(res.getResponseAttachmentSysid() || '');

      if (status >= 200 && status <= 299 && attachmentSysId) {
        return this.finalizeAttachment(attachmentSysId, fileName, res.getHeader('Content-Type'));
      }

      if (attachmentSysId) this.deleteAttachment(attachmentSysId);
      if (status == 429 && attempt < this.maxRetries) {
        gs.warn('Compendia file download rate limited; retrying file_id=' + fileId + ' handbook=' + handbookSlug + ' attempt=' + (attempt + 1));
        continue;
      }
      throw 'Compendia file download failed: HTTP ' + status + ' file_id=' + fileId + ' handbook=' + handbookSlug + ' content_type=' + String(res.getHeader('Content-Type') || '') + ' attachment_sys_id=' + attachmentSysId;
    }
  },

  findExistingAttachment: function (articleSysId, fileName) {
    var names = [fileName];
    var baseName = fileName.replace(/\.[a-z0-9]{2,8}$/i, '');
    var extensions = ['', '.pdf', '.docx', '.doc', '.xlsx', '.pptx'];
    for (var i = 0; i < extensions.length; i++) {
      var candidate = baseName + extensions[i];
      if (names.indexOf(candidate) < 0) names.push(candidate);
    }

    var gr = new GlideRecord('sys_attachment');
    gr.addQuery('table_name', 'kb_knowledge');
    gr.addQuery('table_sys_id', articleSysId);
    gr.addQuery('file_name', 'IN', names.join(','));
    gr.orderByDesc('sys_created_on');
    gr.setLimit(1);
    gr.query();
    if (!gr.next()) return null;
    return {sys_id: String(gr.getUniqueValue()), file_name: String(gr.getValue('file_name')), reused: true};
  },

  finalizeAttachment: function (attachmentSysId, requestedFileName, contentType) {
    var gr = new GlideRecord('sys_attachment');
    if (!gr.get(attachmentSysId)) return {sys_id: attachmentSysId, file_name: requestedFileName, reused: false};

    var cleanType = String(contentType || '').split(';')[0].toLowerCase();
    if (cleanType) gr.setValue('content_type', cleanType);

    var ext = this.extensionForContentType(cleanType);
    var currentName = String(gr.getValue('file_name') || requestedFileName);
    if (ext && !this.hasFileExtension(currentName)) {
      currentName += ext;
      gr.setValue('file_name', currentName);
    }
    gr.update();
    return {sys_id: String(gr.getUniqueValue()), file_name: currentName, reused: false};
  },

  deleteAttachment: function (attachmentSysId) {
    var gr = new GlideRecord('sys_attachment');
    if (gr.get(attachmentSysId)) gr.deleteRecord();
  },

  linkAttachmentTitle: function (html, title, attachmentSysId) {
    var self = this;
    var target = this.normalizeAttachmentTitle(title);
    var linked = false;
    var out = String(html || '').replace(/<li\b([^>]*)>([\s\S]*?)<\/li>/ig, function (whole, attrs, inner) {
      if (linked || /<a\b/i.test(inner)) return whole;
      if (self.normalizeAttachmentTitle(self.stripHtml(inner)) != target) return whole;
      linked = true;
      return '<li' + attrs + '><a href="sys_attachment.do?sys_id=' + attachmentSysId + '" target="_blank" rel="noopener noreferrer">' + self.escapeHtml(self.stripHtml(inner)) + '</a></li>';
    });
    return {html: out, linked: linked};
  },

  attachmentFileName: function (title, fallbackContentType) {
    var name = this.stripHtml(title).replace(/[\\/:*?"<>|]+/g, '-').replace(/^\s+|\s+$/g, '').substring(0, 180);
    if (!name) name = 'compendia-file';
    if (!this.hasFileExtension(name)) name += this.extensionForContentType(fallbackContentType) || '';
    return name;
  },

  extensionForContentType: function (contentType) {
    var cleanType = String(contentType || '').split(';')[0].toLowerCase();
    if (cleanType == 'application/pdf') return '.pdf';
    if (cleanType == 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') return '.docx';
    if (cleanType == 'application/msword') return '.doc';
    if (cleanType == 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet') return '.xlsx';
    if (cleanType == 'application/vnd.openxmlformats-officedocument.presentationml.presentation') return '.pptx';
    return '';
  },

  hasFileExtension: function (fileName) {
    return /\.[a-z0-9]{2,8}$/i.test(String(fileName || ''));
  },

  normalizeAttachmentTitle: function (value) {
    var out = this.decodeBasicEntities(this.stripHtml(value)).toLowerCase();
    out = out.replace(/\.(pdf|docx?|xlsx?|pptx?)$/i, '');
    out = out.replace(/[^0-9a-zæøåäöüéèáàóòíìñ]+/gi, ' ');
    return out.replace(/^\s+|\s+$/g, '').replace(/\s+/g, ' ');
  },

  stripHtml: function (value) {
    return String(value || '').replace(/<[^>]+>/g, ' ');
  },

  decodeBasicEntities: function (value) {
    return String(value || '').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');
  },

  escapeHtml: function (value) {
    return String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  },

  hasRelativeContentUrl: function (html) {
    return /(src|href)=(['"])\/(?!\/)/i.test(String(html || ''));
  },

  targetWorkflowState: function () {
    return gs.getProperty('varenergi.compendia.sync.auto_publish', 'false') == 'true' ? 'published' : 'draft';
  },

  getPages: function (handbookSlug) {
    var data = this.getJson('/' + this.customer + '/' + handbookSlug + '/api/v1/pages');
    return data.pages || [];
  },

  getPage: function (handbookSlug, id) {
    return this.getJson('/' + this.customer + '/' + handbookSlug + '/api/v1/pages/' + encodeURIComponent(id));
  },

  getToken: function () {
    if (this.token) return this.token;
    var rm = new sn_ws.RESTMessageV2();
    rm.setHttpMethod('post');
    rm.setEndpoint(this.base + '/oauth/v2/token');
    rm.setRequestHeader('Content-Type', 'application/json');
    rm.setHttpTimeout(30000);
    rm.setRequestBody(JSON.stringify({client_id: gs.getProperty('varenergi.compendia.client_id'), client_secret: gs.getProperty('varenergi.compendia.client_secret'), grant_type: 'client_credentials'}));
    var res = rm.execute();
    if (res.getStatusCode() < 200 || res.getStatusCode() > 299) throw 'Compendia token failed: HTTP ' + res.getStatusCode();
    this.token = JSON.parse(res.getBody()).access_token;
    return this.token;
  },

  getJson: function (path) {
    for (var attempt = 0; attempt <= this.maxRetries; attempt++) {
      if (attempt > 0 || this.requestDelayMs > 0) gs.sleep(this.requestDelayMs * (attempt + 1));
      var rm = new sn_ws.RESTMessageV2();
      rm.setHttpMethod('get');
      rm.setEndpoint(this.base + path);
      rm.setRequestHeader('Accept', 'application/json');
      rm.setRequestHeader('Authorization', 'Bearer ' + this.getToken());
      rm.setHttpTimeout(30000);
      var res = rm.execute();
      var status = res.getStatusCode();
      if (status >= 200 && status <= 299) return JSON.parse(res.getBody());
      if (status == 429 && attempt < this.maxRetries) {
        gs.warn('Compendia API rate limited; retrying path=' + path + ' attempt=' + (attempt + 1));
        continue;
      }
      throw 'Compendia GET failed: HTTP ' + status + ' path=' + path + ' response=' + String(res.getBody()).substring(0, 300);
    }
  },

  parseHandbooks: function (value) {
    var labels = {'employee': 'Employee', 'leadership-portal': 'Leadership Portal', 'personal': 'Personal', 'personal-offshore': 'Personal Offshore'};
    var raw = String(value || this.handbook || '').split(',');
    var out = [];
    for (var i = 0; i < raw.length; i++) {
      var slug = raw[i].replace(/^\s+|\s+$/g, '');
      if (slug) out.push({slug: slug, name: labels[slug] || slug});
    }
    return out.length ? out : [{slug: this.handbook, name: labels[this.handbook] || this.handbook}];
  },

  languageForHandbook: function (slug) {
    if (slug == 'employee' || slug == 'leadership-portal') return 'en';
    return 'no';
  },

  tagNames: function (page) {
    var names = [];
    var tags = page.tags || [];
    for (var i = 0; i < tags.length; i++) names.push(tags[i].name);
    return names.join(', ');
  },

  buildMeta: function (page, handbook) {
    var tags = this.tagNames(page);
    return [this.source, handbook.name, tags, 'external_key:' + this.externalKey(handbook.slug, page.id)].join('; ');
  },

  externalKey: function (handbookSlug, id) {
    return handbookSlug + ':' + String(id);
  },

  errorResult: function (stage, page, ex) {
    return {ok: false, stage: stage, page_id: page && page.id ? String(page.id) : '', handbook: page && page._handbook_slug ? String(page._handbook_slug) : '', error: String(ex)};
  },

  toGlideDateTime: function (value) {
    var d = new Date(value);
    function p(n) { return n < 10 ? '0' + n : '' + n; }
    return d.getUTCFullYear() + '-' + p(d.getUTCMonth() + 1) + '-' + p(d.getUTCDate()) + ' ' + p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()) + ':' + p(d.getUTCSeconds());
  },

  type: 'VECompendiaKnowledgeSync'
};
